package core

import (
	"fmt"
	"strings"
)

// GlobalConfigName is the generated file (sorting first) holding the
// panel-wide Apache directives.
const GlobalConfigName = "00-panel-global.conf"

// Generator renders Apache config files from the registry. Output is
// deterministic — same registry, byte-identical files — so it can be
// golden-file tested (Plan 10.1). The per-project shape reuses the
// exact directives the M0 spike proved on a real Apache (per-Directory
// FcgidWrapper, no mod_php anywhere, Plan D4/D5).
type Generator struct{}

// GenerateAll renders the global file plus one file per enabled
// project, keyed by file name. Disabled projects generate nothing:
// Apache must not route them at all.
func (Generator) GenerateAll(reg Registry) (map[string]string, error) {
	if err := reg.ValidateStructure(); err != nil {
		return nil, fmt.Errorf("configgen: %w", err)
	}
	out := map[string]string{GlobalConfigName: globalConfig()}
	for _, p := range reg.SortedProjects() {
		if !p.Enabled {
			continue
		}
		php, _ := reg.FindPHP(p.PHPVersion)
		out[p.Name+".conf"] = generateProject(reg.Settings.DocumentRoot, p, php)
	}
	return out, nil
}

func globalConfig() string {
	var b strings.Builder
	b.WriteString("# Generated by SPanel+ - DO NOT EDIT. Change projects through the panel/CLI.\n")
	b.WriteString("# Panel-wide directives. The fcgid module itself is loaded by httpd.conf (adoption step);\n")
	b.WriteString("# doctor verifies mod_fcgid is present and matching.\n\n")
	b.WriteString("<IfModule dir_module>\n")
	b.WriteString("    DirectoryIndex index.php index.html\n")
	b.WriteString("</IfModule>\n\n")
	b.WriteString("<IfModule fcgid_module>\n")
	b.WriteString("    FcgidMaxProcesses 20\n")
	b.WriteString("    FcgidMaxProcessesPerClass 10\n")
	b.WriteString("    FcgidMaxRequestsPerProcess 1000\n")
	b.WriteString("    FcgidIOTimeout 120\n")
	b.WriteString("    FcgidBusyTimeout 300\n")
	b.WriteString("    FcgidIdleTimeout 120\n")
	b.WriteString("    FcgidInitialEnv PHP_FCGI_MAX_REQUESTS 1000\n")
	b.WriteString("    FcgidInitialEnv SystemRoot \"C:/Windows\"\n")
	b.WriteString("    FcgidInitialEnv SystemDrive \"C:\"\n")
	b.WriteString("    FcgidInitialEnv TEMP \"C:/Windows/Temp\"\n")
	b.WriteString("    FcgidInitialEnv TMP \"C:/Windows/Temp\"\n")
	b.WriteString("    FcgidInitialEnv windir \"C:/Windows\"\n")
	b.WriteString("</IfModule>\n")
	return b.String()
}

func generateProject(documentRoot string, p Project, php PHPVersion) string {
	target := slashPath(p.TargetDir())
	var b strings.Builder
	fmt.Fprintf(&b, "# Generated by SPanel+ - DO NOT EDIT. Project: %s (%s)\n", p.Name, p.Type)
	if p.Type != ProjectStatic {
		fmt.Fprintf(&b, "# PHP: %s (%s)\n", php.Version, slashPath(php.Path))
	}
	b.WriteString("\n")

	// An Alias is needed whenever the URL path does not naturally map
	// onto the target dir under the DocumentRoot. For Laravel that is
	// always the case — the Alias to public/ is exactly what removes
	// /public from the URL and keeps the project root (with .env)
	// off the web (Plan D5).
	if needsAlias(documentRoot, p, target) {
		fmt.Fprintf(&b, "Alias \"%s\" \"%s\"\n", p.URLPath, target)
	}
	fmt.Fprintf(&b, "<Directory \"%s\">\n", target)
	if p.Type == ProjectStatic {
		b.WriteString("    AllowOverride None\n")
	} else {
		b.WriteString("    Options +ExecCGI\n")
		b.WriteString("    AllowOverride All\n")
	}
	b.WriteString("    Require all granted\n")
	if p.Type != ProjectStatic {
		b.WriteString("    <FilesMatch \"\\.php$\">\n")
		b.WriteString("        SetHandler fcgid-script\n")
		b.WriteString("    </FilesMatch>\n")
		fmt.Fprintf(&b, "    FcgidWrapper \"%s/php-cgi.exe\" .php\n", slashPath(php.Path))
	}
	b.WriteString("</Directory>\n")
	return b.String()
}

// needsAlias reports whether url_path -> target needs an explicit
// Alias, i.e. the target is not exactly DocumentRoot+url_path.
func needsAlias(documentRoot string, p Project, targetSlash string) bool {
	if p.Type == ProjectLaravel || p.Type == ProjectCI4 {
		return true
	}
	if documentRoot == "" {
		return true
	}
	return slashPath(documentRoot)+p.URLPath != targetSlash
}

// slashPath normalizes a Windows path for Apache config use:
// forward slashes, no trailing slash.
func slashPath(p string) string {
	return strings.TrimRight(strings.ReplaceAll(p, "\\", "/"), "/")
}
